command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-paging --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "ca2928e28623ee8813d4077eb551e8df258d8a43") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-paging).Trim() -ne "40f126fdc3225c41e6a3a5fbc7534f0d36522d11") { throw "candidate moved" }

git checkout work/large-folder-paging
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/large-folder-paging
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

$delta=@(git diff --name-only d5fe043b65c483cae11370220362df0f458082d2..HEAD)
if ($delta.Count -ne 1 -or $delta[0] -ne "tests/winui/helper/test_winui_integration_contract.py") {
  throw "post-failure revision changed more than source contract"
}

Write-Host "SOURCE_CONTRACTS"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "HELPER_PROTOCOL_V3"
$env:FLY_M16_CONFIG="Release"
python -X utf8 tests\winui\helper\test_process_isolation.py
if ($LASTEXITCODE -ne 0) { throw "helper protocol v3 regression failed" }

Write-Host "OWNED_8000_FOLDER_GUI"
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 8000 --configuration Release
if ($LASTEXITCODE -ne 0) { throw "8000-file owned GUI failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_PAGED_TRANSPORT_PREMAIN_PASS"
